input.command:
$py = @'
import openpyxl, sys
wb = openpyxl.load_workbook(sys.argv[1], data_only=False)
for ws in wb.worksheets:
    print(f"=== {ws.title} dims={ws.dimensions} merged={len(ws.merged_cells.ranges)}")
    for row in ws.iter_rows():
        vals = [(c.coordinate, c.value) for c in row if c.value is not None]
        if vals: print(" | ".join(f"{k}={v}" for k,v in vals))
    if ws.data_validations.dataValidation: print("DV:", [(d.sqref, d.formula1) for d in ws.data_validations.dataValidation])
    print("CF:", len(ws.conditional_formatting))
    for c in [ws.cell(r,cc) for r in range(1,4) for cc in range(1,4)]:
        if c.comment: print("comment", c.coordinate, c.comment.text)
'@
