$py = @'
import sys, openpyxl, zipfile, hashlib
a = openpyxl.load_workbook(sys.argv[1], read_only=True); b = openpyxl.load_workbook(sys.argv[2], read_only=True)
assert a.sheetnames == b.sheetnames, (a.sheetnames, b.sheetnames)
from collections import Counter
for n in a.sheetnames:
    diff = Counter(); ex = []
    for ra, rb_ in zip(a[n].iter_rows(), b[n].iter_rows()):
        for ca, cb in zip(ra, rb_):
            if getattr(ca, "value", None) != getattr(cb, "value", None):
                diff[ca.column_letter] += 1
                if len(ex) < 2: ex.append((ca.coordinate, str(cb.value)[:160]))
    if diff: print(n, dict(diff), ex)
for p in sys.argv[1:]:
    with zipfile.ZipFile(p) as z:
        print([ (i, hashlib.md5(z.read(i)).hexdigest()[:10]) for i in z.namelist() if i.startswith("customXml/item")])
